const WORK = "/oracle/work";
const OTHER_WORK = "/oracle/child-work";
const instanceId = ProviderInstanceId.make("opencode");
const modelSelection = { instanceId, model: "opencode/big-pickle" };
const policy = (cwd = WORK) => ({
  runtimeMode: "full-access" as const,
  interactionMode: "default" as const,
  cwd,
});
const parentId = ThreadId.make("oracle:parent");
const childId = ThreadId.make("oracle:child");
const ordinaryId = ThreadId.make("oracle:ordinary");
const nativeIdOf = (thread: OrchestrationV2ProviderThread) => {
  const id = thread.nativeThreadRef?.nativeId;
  if (typeof id !== "string") throw new Error("Fixture expected an actual native session");
  return id;
};
type Rule = { action: string; resource: string; effect: string };
type Native = {
  id: string;
  title: string;
  permissions: Rule[];
  projectID: string;
  model: { id: string; providerID: string; variant: string };
  cost: number;
  tokens: {
    input: number;
    output: number;
    reasoning: number;
    cache: { read: number; write: number };
  };
  time: { created: number; updated: number };
  location: { directory: string };
};
type Registration = {
  directory: string;
  server: string;
  config: { url: string; headers: { Authorization: string } };
};
type Identity = { name: string; threadId: string };
const glob = (pattern: string, value: string) => {
  const parts = pattern.split("*");
  if (parts.length === 1) return pattern === value;
  if (!value.startsWith(parts[0]!) || !value.endsWith(parts.at(-1)!)) return false;
  let from = parts[0]!.length;
  for (const part of parts.slice(1, -1)) {
    const at = value.indexOf(part, from);
    if (at < 0) return false;
    from = at + part.length;
  }
  return true;
};

const makeFake = () => {
  const sessions = new Map<string, Native>();
  const registrations = new Map<string, Registration>();
  const identities = new Map<string, string>();
  const unavailable = new Set<string>();
  const instructions = new Map<string, string>();
  const snapshots: Array<{ sessionID: string; tools: Identity[]; instructions: string }> = [];
  const requests: string[] = [];
  let nextId = 0;
  let forkCount = 0;
  let events: ReadableStreamDefaultController<Uint8Array> | undefined;
  const native = (directory: string, permissions: Rule[], title = "Oracle"): Native => ({
    id: `ses_oracle${++nextId}`,
    title,
    permissions,
    projectID: "global",
    model: { id: "big-pickle", providerID: "opencode", variant: "default" },
    cost: 0,
    tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
    time: { created: 1790656601394, updated: 1790656601394 },
    location: { directory },
  });
  const authorize = (registration: Registration) =>
    identities.get(`${registration.config.url}\n${registration.config.headers.Authorization}`);
  const catalog = (sessionID: string): Identity[] => {
    const session = sessions.get(sessionID)!;
    const tools: Identity[] = [];
    for (const registration of registrations.values()) {
      const threadId = authorize(registration);
      const name = `${registration.server}_identity`;
      const rule = session.permissions.findLast(
        (rule) => glob(rule.action, name) && glob(rule.resource, "*"),
      );
      if (
        registration.directory === session.location.directory &&
        threadId !== undefined &&
        rule?.effect === "allow"
      )
        tools.push({ name, threadId });
    }
    return tools;
  };
  const invoke = (sessionID: string, name: string) => {
    const tool = catalog(sessionID).find((tool) => tool.name === name);
    if (!tool) throw new Error("identity tool unavailable");
    return { threadId: tool.threadId };
  };
  const client = HttpClient.make((request, url) =>
    Effect.sync(() => {
      const body =
        request.body._tag === "Uint8Array"
          ? (JSON.parse(new TextDecoder().decode(request.body.body)) as Record<string, unknown>)
          : {};
      const path = url.pathname;
      requests.push(`${request.method} ${path}`);
      const json = (value: unknown, status = 200) =>
        HttpClientResponse.fromWeb(
          request,
          new Response(JSON.stringify(value), {
            status,
            headers: { "content-type": "application/json" },
          }),
        );
      const empty = () => HttpClientResponse.fromWeb(request, new Response(null, { status: 204 }));
      if (path === "/api/event")
        return HttpClientResponse.fromWeb(
          request,
          new Response(
            new ReadableStream<Uint8Array>({
              start(controller) {
                events = controller;
              },
            }),
            { headers: { "content-type": "text/event-stream" } },
          ),
        );
      if (path === "/api/model")
        return json({
          location: { directory: url.searchParams.get("location[directory]") ?? WORK },
          data: [
            {
              id: "big-pickle",
              modelID: "big-pickle",
              providerID: "opencode",
              family: "big-pickle",
              name: "Big Pickle",
              compatibility: { reasoningField: "reasoning_content" },
              package: "@opencode/ai/providers/openai-compatible",
              settings: {},
              capabilities: { tools: true, input: ["text"], output: ["text"] },
              variants: [],
              time: { released: 1760659200000 },
              cost: [{ input: 0, output: 0, cache: { read: 0, write: 0 } }],
              status: "active",
              enabled: true,
              limit: { context: 200000, input: 160000, output: 32000 },
            },
          ],
        });
      if (path === "/api/agent")
        return json({
          location: { directory: WORK },
          data: [
            {
              id: "build",
              name: "Build",
              request: { settings: {}, headers: {}, body: {} },
              description: "Default",
              mode: "primary",
              hidden: false,
              permissions: [{ action: "*", resource: "*", effect: "allow" }],
            },
          ],
        });
      if (path === "/api/session/active") return json({ data: [] });
      const segments = path.split("/").filter(Boolean).map(decodeURIComponent);
      if (segments[1] === "experimental" && segments[2] === "mcp") {
        const server = segments[3]!;
        const directory = url.searchParams.get("location[directory]")!;
        const key = `${directory}\n${server}`;
        if (request.method === "DELETE") {
          registrations.delete(key);
          return empty();
        }
        const config = body.config as Registration["config"];
        if (unavailable.has(config.headers.Authorization))
          return json({ message: "Synthetic MCP unavailable" }, 500);
        if (!identities.has(`${config.url}\n${config.headers.Authorization}`))
          return json({ message: "Synthetic unauthorized" }, 401);
        registrations.set(key, { server, directory, config });
        return empty();
      }
      if (
        segments[1] === "experimental" &&
        segments[2] === "session" &&
        segments[4] === "instructions"
      ) {
        instructions.set(segments[3]!, String(body.value));
        return empty();
      }
      if (path === "/api/session" && request.method === "POST") {
        const session = native(
          (body.location as { directory: string }).directory,
          body.permissions as Rule[],
          body.title as string,
        );
        sessions.set(session.id, session);
        return json({ data: session });
      }
      if (segments[1] === "session") {
        const id = segments[2]!;
        const session = sessions.get(id);
        if (!session) throw new Error(`Unknown synthetic session ${id}`);
        const operation = segments[3];
        if (!operation && request.method === "GET") return json({ data: session });
        if (!operation && request.method === "PATCH") {
          Object.assign(
            session,
            Object.fromEntries(Object.entries(body).filter(([, value]) => value !== null)),
          );
          return empty();
        }
        if (operation === "fork") {
          forkCount++;
          const fork = native(
            session.location.directory,
            structuredClone(session.permissions),
            session.title,
          );
          sessions.set(fork.id, fork);
          return json({ data: fork });
        }
        if (operation === "move") {
          session.location.directory = String(body.directory);
          return empty();
        }
        if (operation === "model") {
          session.model = body.model as Native["model"];
          return empty();
        }
        if (operation === "agent" || operation === "interrupt") return empty();
        if (operation === "permission" || operation === "form") return json({ data: [] });
        if (operation === "message") return json({ data: [], cursor: {} });
        if (operation === "prompt") {
          snapshots.push({
            sessionID: id,
            tools: catalog(id),
            instructions: instructions.get(id) ?? "",
          });
          return json({
            data: {
              id: body.id,
              sessionID: id,
              time: { created: 1790656601410 },
              type: "user",
              payload: { text: body.text },
              delivery: "steer",
            },
          });
        }
      }
      throw new Error(`Unhandled synthetic HTTP ${request.method} ${path} ${JSON.stringify(body)}`);
    }),
  );
  return {
    client,
    registrations,
    identities,
    unavailable,
    instructions,
    snapshots,
    sessions,
    catalog,
    invoke,
    requests,
    get forkCount() {
      return forkCount;
    },
    complete(sessionID: string) {
      events!.enqueue(
        new TextEncoder().encode(
          `data: ${JSON.stringify({ id: `evt_oracle${snapshots.length}`, created: 1, type: "session.execution.succeeded", data: { sessionID }, durable: { aggregateID: sessionID, seq: snapshots.length, version: 1 } })}\n\n`,
        ),
      );
    },
  };
};

const hostLayer = TestProviderHost.layer({ cwd: WORK }).pipe(Layer.provide(NodeServices.layer));
const deps = Layer.mergeAll(
  NodeServices.layer,
  hostLayer,
  IdAllocator.layer,
  McpProviderSessions.layer,
);
const setup = (managed = false) =>
  Effect.gen(function* () {
    const fake = makeFake();
    const mcp = yield* McpProviderSessions.McpProviderSessions;
    const credentialKeys = new Map<string, string>();
    const config = (threadId: ThreadId, suffix = "initial") => ({
      environmentId: EnvironmentId.make("oracle:environment"),
      threadId,
      providerSessionId: `oracle-session:${threadId}:${suffix}`,
      providerInstanceId: instanceId,
      endpoint: "http://oracle-mcp.invalid/mcp",
      authorizationHeader: `Bearer synthetic:${threadId}:${suffix}`,
      browserToolsAvailable: false,
    });
    const issue = (threadId: ThreadId, suffix = "initial") =>
      Effect.gen(function* () {
        const slot = config(threadId, suffix);
        for (const [key, owner] of fake.identities)
          if (owner === threadId) fake.identities.delete(key);
        const identityKey = `${slot.endpoint}\n${slot.authorizationHeader}`;
        fake.identities.set(identityKey, threadId);
        credentialKeys.set(slot.providerSessionId, identityKey);
        yield* mcp.set(slot);
        return slot;
      });
    if (!managed) for (const id of [parentId, childId, ordinaryId]) yield* issue(id);
    const api = yield* OpenCode2Client.make.pipe(
      Effect.provideService(HttpClient.HttpClient, fake.client),
    );
    const connection = {
      ...(yield* api.connect({ baseUrl: "http://oracle-opencode.invalid", password: "synthetic" })),
      url: "http://oracle-opencode.invalid",
      version: "2.0.18",
      external: false,
    };
    const adapter = yield* Adapter.make(instanceId).pipe(
      Effect.provideService(OpenCode2Server.OpenCode2Server, {
        withConnection: (use) => use(connection),
      }),
    );
    const providerSessionId = ProviderSessionId.make("oracle:runtime");
    const openInput = {
      threadId: parentId,
      providerSessionId,
      modelSelection,
      runtimePolicy: policy(managed ? process.cwd() : WORK),
    };
    let manager: ProviderSessionManager.ProviderSessionManagerV2["Service"] | undefined;
    if (managed) {
      const stores = Layer.merge(EventStore.layer, ProjectionStore.layer).pipe(
        Layer.provide(Sqlite.layerMemory),
      );
      const sink = EventSink.layer.pipe(Layer.provide(Layer.merge(stores, Sqlite.layerMemory)));
      let sequence = 0;
      const revoke = (threadId: ThreadId) =>
        Effect.sync(() => {
          for (const [key, owner] of fake.identities)
            if (owner === threadId) fake.identities.delete(key);
        });
      const registry = Layer.succeed(McpSessionRegistry.McpSessionRegistry, {
        issue: (request) =>
          Effect.gen(function* () {
            const slot = yield* issue(request.threadId, `managed${++sequence}`);
            return {
              config: {
                ...slot,
                ...(request.capabilities === undefined
                  ? {}
                  : { capabilities: request.capabilities }),
                browserToolsAvailable: request.browserToolsAvailable ?? true,
              },
            };
          }),
        resolve: (raw) =>
          Effect.sync(() => {
            const owner = fake.identities.get(`http://oracle-mcp.invalid/mcp\nBearer ${raw}`);
            return owner === undefined
              ? undefined
              : {
                  environmentId: EnvironmentId.make("oracle:environment"),
                  requestNamespace: `synthetic:${owner}`,
                  thread: {
                    threadId: ThreadId.make(owner),
                    providerSessionId: `oracle-session:${owner}`,
                    providerInstanceId: instanceId,
                    subagent: false,
                  },
                  client: undefined,
                  capabilities: new Set([
                    "orchestration",
                    "worktree",
                    "pull-requests",
                    "preview",
                  ] as const),
                  issuedAt: 0,
                };
          }),
        touch: () => Effect.void,
        revokeThread: revoke,
        revokeProviderSession: (credential) =>
          Effect.sync(() => {
            const key = credentialKeys.get(credential);
            if (key !== undefined) fake.identities.delete(key);
            credentialKeys.delete(credential);
          }),
        revokeAll: Effect.sync(() => fake.identities.clear()),
      });
      const managerLayer = ProviderSessionManager.layerWithOptions({ idleTimeoutMs: 3600000 }).pipe(
        Layer.provide(
          Layer.mergeAll(
            ProviderAdapterRegistry.layerSingle(adapter),
            registry,
            stores,
            sink,
            CommandOutputHub.layer.pipe(Layer.provide(Layer.merge(sink, stores))),
            Layer.mock(ProviderEventIngestor.ProviderEventIngestorV2)({}),
          ),
        ),
      );
      const context = yield* Layer.build(Layer.mergeAll(managerLayer, sink, stores));
      manager = yield* Effect.service(ProviderSessionManager.ProviderSessionManagerV2).pipe(
        Effect.provide(context),
      );
      const eventSink = yield* Effect.service(EventSink.EventSinkV2).pipe(Effect.provide(context));
      const allocator = yield* IdAllocator.IdAllocatorV2;
      const now = yield* DateTime.now;
      const projectId = yield* allocator.allocate.project({ fixtureName: "oracle" });
      for (const id of [parentId, childId, ordinaryId]) {
        yield* eventSink.write({
          events: [
            {
              id: yield* allocator.allocate.event({ threadId: id }),
              type: "thread.created",
              threadId: id,
              occurredAt: now,
              payload: {
                id,
                projectId,
                title: "Oracle",
                createdBy: "user",
                creationSource: "web",
                providerInstanceId: instanceId,
                modelSelection,
                runtimeMode: "full-access",
                interactionMode: "default",
                branch: null,
                worktreePath: null,
                activeProviderThreadId: null,
                lineage: { parentThreadId: null, relationshipToParent: null, rootThreadId: id },
                forkedFrom: null,
                createdAt: now,
                updatedAt: now,
                archivedAt: null,
                settledOverride: null,
                settledAt: null,
                lastVisitedAt: null,
                deletedAt: null,
              },
            },
          ],
        });
      }
    }
    let currentScope: Scope.Closeable | undefined;
    const stop = () =>
      manager
        ? manager.close(providerSessionId)
        : currentScope
          ? Scope.close(currentScope, Exit.void)
          : Effect.void;
    const open = () =>
      Effect.gen(function* () {
        if (manager) return yield* manager.open(openInput);
        const scope = yield* Scope.make();
        currentScope = scope;
        yield* Effect.addFinalizer(() => Scope.close(scope, Exit.void));
        return yield* adapter
          .openSession(openInput)
          .pipe(Effect.provideService(Scope.Scope, currentScope));
      });
    const restart = () => stop().pipe(Effect.andThen(open()));
    const runtime = yield* open();
    const ensure = (id: ThreadId, cwd = WORK) =>
      runtime.ensureThread({
        threadId: id,
        modelSelection,
        runtimePolicy: policy(cwd),
        title: "Oracle",
      });
    const parent = yield* ensure(parentId);
    let turnCount = 0;
    const prompt = (
      current: ProviderAdapter.ProviderAdapterV2SessionRuntime,
      thread: OrchestrationV2ProviderThread,
      cwd = WORK,
    ) =>
      Effect.gen(function* () {
        const n = ++turnCount;
        const terminal = yield* current.events.pipe(
          Stream.filter((event) => event.type === "turn.terminal"),
          Stream.runHead,
          Effect.forkScoped,
        );
        yield* current.startTurn({
          appThread: { title: "Oracle" } as OrchestrationV2AppThread,
          threadId: thread.appThreadId!,
          runId: RunId.make(`oracle:run${n}`),
          runOrdinal: n,
          providerTurnOrdinal: n,
          attemptId: RunAttemptId.make(`oracle:attempt${n}`),
          rootNodeId: NodeId.make(`oracle:node${n}`),
          providerThread: thread,
          message: {
            messageId: MessageId.make(`oracle:message${n}`),
            text: "Inspect available tools",
            attachments: [],
            createdBy: "user",
            creationSource: "web",
            scheduledTaskId: undefined,
            senderThreadId: undefined,
          },
          modelSelection,
          runtimePolicy: policy(cwd),
        });
        fake.complete(nativeIdOf(thread));
        const ended = yield* Fiber.join(terminal);
        assert.equal(Option.getOrUndefined(ended)?.type, "turn.terminal");
        return fake.snapshots.at(-1)!;
      });
    yield* prompt(runtime, parent);
    const fork = (cwd = WORK) =>
      runtime.forkThread({
        sourceProviderThread: parent,
        targetThreadId: childId,
        runtimePolicy: policy(cwd),
      });
    const expectIdentity = (thread: OrchestrationV2ProviderThread, expected: ThreadId) => {
      const nativeId = nativeIdOf(thread);
      const tools = fake.catalog(nativeId);
      assert.deepEqual(
        tools.map((tool) => tool.threadId),
        [expected],
      );
      assert.deepEqual(fake.invoke(nativeId, tools[0]!.name), { threadId: expected });
    };
    return {
      fake,
      runtime,
      parent,
      fork,
      prompt,
      expectIdentity,
      ensure,
      open,
      restart,
      issue,
      manager,
    };
  });

it.effect("F0: fork return exposes child identity capability and preserves parent", () =>
  Effect.gen(function* () {
    const h = yield* setup();
    const child = yield* h.fork();
    assert.equal(h.fake.forkCount, 1);
    h.expectIdentity(h.parent, parentId);
    assert.deepEqual(
      h.fake.catalog(nativeIdOf(child)).map((tool) => tool.threadId),
      [childId],
      "F0 missing child capability immediately after native fork returns",
    );
    h.expectIdentity(child, childId);
  }).pipe(Effect.scoped, Effect.provide(deps)),
);

it.effect(
  "F1: first child prompt sees its own identity with no parent bleed; ordinary thread works",
  () =>
    Effect.gen(function* () {
      const h = yield* setup();
      const child = yield* h.fork();
      const first = yield* h.prompt(h.runtime, child);
      assert.deepEqual(
        first.tools.map((tool) => tool.threadId),
        [childId],
        "F1 effective prompt catalog",
      );
      h.expectIdentity(child, childId);
      h.expectIdentity(h.parent, parentId);
      const parentTool = h.fake.catalog(nativeIdOf(h.parent))[0]!;
      const childTool = h.fake.catalog(nativeIdOf(child))[0]!;
      assert.throws(
        () => h.fake.invoke(nativeIdOf(child), parentTool.name),
        "identity tool unavailable",
      );
      assert.throws(
        () => h.fake.invoke(nativeIdOf(h.parent), childTool.name),
        "identity tool unavailable",
      );
      const ordinary = yield* h.ensure(ordinaryId);
      const control = yield* h.prompt(h.runtime, ordinary);
      assert.deepEqual(
        control.tools.map((tool) => tool.threadId),
        [ordinaryId],
      );
      h.expectIdentity(ordinary, ordinaryId);
      const parent = yield* h.prompt(h.runtime, h.parent);
      assert.deepEqual(
        parent.tools.map((tool) => tool.threadId),
        [parentId],
      );
      assert.equal(h.fake.forkCount, 1);
    }).pipe(Effect.scoped, Effect.provide(deps)),
);

it.effect(
  "restart/resume keeps one effective child registration and rotates scoped identity credentials",
  () =>
    Effect.gen(function* () {
      const h = yield* setup();
      const child = yield* h.fork(OTHER_WORK);
      const restarted = yield* h.restart();
      yield* restarted.resumeThread({
        providerThread: h.parent,
        threadId: parentId,
        modelSelection,
        runtimePolicy: policy(),
      });
      yield* h.prompt(restarted, h.parent);
      yield* restarted.resumeThread({
        providerThread: child,
        threadId: childId,
        modelSelection,
        runtimePolicy: policy(OTHER_WORK),
      });
      yield* h.issue(childId, "rotated");
      yield* h.prompt(restarted, child, OTHER_WORK);
      yield* restarted.resumeThread({
        providerThread: child,
        threadId: childId,
        modelSelection,
        runtimePolicy: policy(OTHER_WORK),
      });
      yield* h.prompt(restarted, child, OTHER_WORK);
      h.expectIdentity(child, childId);
      h.expectIdentity(h.parent, parentId);
      assert.equal(
        [...h.fake.registrations.values()].filter(
          (registration) =>
            h.fake.identities.get(
              `${registration.config.url}\n${registration.config.headers.Authorization}`,
            ) === childId,
        ).length,
        1,
      );
      assert.isTrue(
        [...h.fake.registrations.values()].some(
          (registration) =>
            registration.config.headers.Authorization === `Bearer synthetic:${childId}:rotated`,
        ),
      );
    }).pipe(Effect.scoped, Effect.provide(deps)),
);

it.effect("unavailable child registration is observable and recovers without parent bleed", () => {
  const logs: Array<{ level: string; message: unknown }> = [];
  return Effect.gen(function* () {
    const h = yield* setup();
    h.fake.unavailable.add(`Bearer synthetic:${childId}:initial`);
    const result = yield* h.fork().pipe(Effect.exit);
    h.expectIdentity(h.parent, parentId);
    if (Exit.isFailure(result)) {
      assert.include(Cause.pretty(result.cause), "MCP");
      return;
    }
    const child = result.value;
    const failed = yield* h.prompt(h.runtime, child);
    assert.deepEqual(failed.tools, []);
    assert.notEqual(
      failed.instructions,
      h.fake.snapshots[0]!.instructions,
      "availability must affect model-visible instructions",
    );
    assert.isTrue(
      logs.some((log) => log.level === "Warn" && JSON.stringify(log.message).includes("MCP")),
      "MCP registration failure must be observable",
    );
    h.expectIdentity(h.parent, parentId);
    h.fake.unavailable.clear();
    const recovered = yield* h.prompt(h.runtime, child);
    assert.deepEqual(
      recovered.tools.map((tool) => tool.threadId),
      [childId],
    );
    h.expectIdentity(child, childId);
  }).pipe(
    Effect.scoped,
    Effect.provide(
      Layer.mergeAll(
        deps,
        Logger.layer(
          [Logger.make(({ logLevel, message }) => logs.push({ level: logLevel, message }))],
          { mergeWithExisting: false },
        ),
        Layer.succeed(References.MinimumLogLevel, "Warn"),
      ),
    ),
  );
});

it.effect(
  "service F0: managed native fork returns a child with effective scoped MCP capability",
  () =>
    Effect.gen(function* () {
      const h = yield* setup(true);
      const child = yield* h.fork(OTHER_WORK);
      assert.equal(h.fake.forkCount, 1);
      const slots = yield* McpProviderSessions.McpProviderSessions;
      const childSlot = yield* slots.read(childId);
      const parentSlot = yield* slots.read(parentId);
      assert.isDefined(childSlot, "manager issued child credentials");
      assert.notEqual(childSlot!.authorizationHeader, parentSlot!.authorizationHeader);
      h.expectIdentity(h.parent, parentId);
      assert.deepEqual(
        h.fake.catalog(nativeIdOf(child)).map((tool) => tool.threadId),
        [childId],
        "service F0 missing child capability despite issued credentials",
      );
    }).pipe(Effect.scoped, Effect.provide(deps)),
);

it.effect(
  "service F1: child first prompt uses manager-issued child credentials and ordinary thread remains usable",
  () =>
    Effect.gen(function* () {
      const h = yield* setup(true);
      const child = yield* h.fork();
      const first = yield* h.prompt(h.runtime, child);
      assert.deepEqual(
        first.tools.map((tool) => tool.threadId),
        [childId],
      );
      h.expectIdentity(child, childId);
      h.expectIdentity(h.parent, parentId);
      const parentTool = h.fake.catalog(nativeIdOf(h.parent))[0]!;
      const childTool = h.fake.catalog(nativeIdOf(child))[0]!;
      assert.throws(
        () => h.fake.invoke(nativeIdOf(child), parentTool.name),
        "identity tool unavailable",
      );
      assert.throws(
        () => h.fake.invoke(nativeIdOf(h.parent), childTool.name),
        "identity tool unavailable",
      );
      const ordinary = yield* h.ensure(ordinaryId);
      const control = yield* h.prompt(h.runtime, ordinary);
      assert.deepEqual(
        control.tools.map((tool) => tool.threadId),
        [ordinaryId],
      );
      yield* h.runtime.resumeThread({
        providerThread: child,
        threadId: childId,
        modelSelection,
        runtimePolicy: policy(),
      });
      yield* h.prompt(h.runtime, child);
      h.expectIdentity(child, childId);
      assert.equal(h.fake.catalog(nativeIdOf(child)).length, 1);
    }).pipe(Effect.scoped, Effect.provide(deps)),
);

it.effect(
  "service restart heals child prompt capability with fresh credentials and one effective registration",
  () =>
    Effect.gen(function* () {
      const h = yield* setup(true);
      const child = yield* h.fork();
      const slots = yield* McpProviderSessions.McpProviderSessions;
      const oldSlot = yield* slots.read(childId);
      assert.isDefined(oldSlot);
      const restarted = yield* h.restart();
      yield* restarted.resumeThread({
        providerThread: h.parent,
        threadId: parentId,
        modelSelection,
        runtimePolicy: policy(),
      });
      yield* h.prompt(restarted, h.parent);
      yield* restarted.resumeThread({
        providerThread: child,
        threadId: childId,
        modelSelection,
        runtimePolicy: policy(),
      });
      const healed = yield* h.prompt(restarted, child);
      assert.deepEqual(
        healed.tools.map((tool) => tool.threadId),
        [childId],
      );
      const renewedSlot = yield* slots.read(childId);
      assert.isDefined(renewedSlot);
      assert.notEqual(renewedSlot!.authorizationHeader, oldSlot!.authorizationHeader);
      assert.isFalse(
        h.fake.identities.has(`${oldSlot!.endpoint}\n${oldSlot!.authorizationHeader}`),
      );
      yield* restarted.resumeThread({
        providerThread: child,
        threadId: childId,
        modelSelection,
        runtimePolicy: policy(),
      });
      yield* h.prompt(restarted, child);
      h.expectIdentity(child, childId);
      h.expectIdentity(h.parent, parentId);
      assert.equal(h.fake.catalog(nativeIdOf(child)).length, 1);
    }).pipe(Effect.scoped, Effect.provide(deps)),
);

